"use client";

import { useState } from "react";

const gcd = (a: number, b: number): number => (b === 0 ? Math.abs(a) : gcd(b, a % b));

/** The ideal of ℤ generated by a and b: all ax + by, which turns out to be the multiples of gcd(a, b). */
export function IdealGenViz() {
  const [a, setA] = useState(12);
  const [b, setB] = useState(18);
  const [reach, setReach] = useState(1);
  const R = 30;
  const hit = new Map<number, [number, number]>();
  for (let x = -reach; x <= reach; x++) for (let y = -reach; y <= reach; y++) {
    const v = a * x + b * y;
    if (Math.abs(v) <= R && !hit.has(v)) hit.set(v, [x, y]);
  }
  const g = gcd(a, b);
  const all = Array.from({ length: 2 * R + 1 }, (_, i) => i - R).filter((v) => v % g === 0);
  const done = all.every((v) => hit.has(v));
  const W = 560, x0 = 20, step = (W - 40) / (2 * R);
  const px = (v: number) => x0 + (v + R) * step;
  const gx = hit.get(g);
  return (
    <figure className="viz">
      <div className="viz-sliders">
        <label><span>a: <span className="mono">{a}</span></span>
          <input type="range" min={1} max={30} value={a} onChange={(ev) => setA(Math.round(Number(ev.target.value)))} /></label>
        <label><span>b: <span className="mono">{b}</span></span>
          <input type="range" min={1} max={30} value={b} onChange={(ev) => setB(Math.round(Number(ev.target.value)))} /></label>
        <label><span>coefficients up to: <span className="mono">±{reach}</span></span>
          <input type="range" min={0} max={8} value={reach} onChange={(ev) => setReach(Math.round(Number(ev.target.value)))} /></label>
      </div>
      <svg viewBox={`0 0 ${W} 70`} role="img" aria-label="Integers between −30 and 30 reached as ax + by" style={{ width: "100%", display: "block" }}>
        <line x1={x0} y1={30} x2={W - 20} y2={30} style={{ stroke: "var(--border-strong)" }} />
        {Array.from({ length: 2 * R + 1 }, (_, i) => i - R).map((v) => (
          <g key={v}>
            {v % g === 0 && <circle cx={px(v)} cy={30} r={6} style={{ fill: "none", stroke: "var(--accent)", strokeDasharray: "2 2" }} />}
            <circle cx={px(v)} cy={30} r={hit.has(v) ? 4.5 : 1.8} style={{ fill: hit.has(v) ? "var(--accent)" : "var(--text-faint)" }} />
            {v % 10 === 0 && <text x={px(v)} y={56} textAnchor="middle" className="mono" style={{ fill: "var(--text-muted)", fontSize: 11 }}>{v}</text>}
          </g>
        ))}
      </svg>
      <p className="mono" style={{ margin: "4px 0" }}>
        gcd({a}, {b}) = {g}; {gx ? `${g} = ${a}·(${gx[0]}) + ${b}·(${gx[1]})` : `${g} not reached yet`}{done ? "; every multiple of " + g + " in view is reached" : ""}
      </p>
      <figcaption className="viz-caption">
        Filled dots are numbers of the form ax + by with the coefficients allowed so far; rings mark the multiples of gcd(a, b). Widen the coefficients and the filled dots fill exactly the rings. The ideal generated by a and b is the principal ideal generated by their gcd.
      </figcaption>
    </figure>
  );
}
